package com.zpantry.media.service; import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.io.ByteArrayResource;import org.springframework.http.client.MultipartBodyBuilder;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import org.springframework.web.multipart.MultipartFile;
@Component public class CloudinaryMediaStorageAdapter implements MediaStoragePort{private final RestClient client;private final String cloud,key,secret;public CloudinaryMediaStorageAdapter(@Value("${zpantry.media.cloudinary.cloud-name:}")String c,@Value("${zpantry.media.cloudinary.api-key:}")String k,@Value("${zpantry.media.cloudinary.api-secret:}")String s){cloud=c;key=k;secret=s;client=RestClient.builder().baseUrl("https://api.cloudinary.com/v1_1/"+c).build();}
 public UploadResult upload(MultipartFile f,String folder){configured();try{long ts=Instant.now().getEpochSecond();String sig=sha1("folder="+folder+"&timestamp="+ts+secret);MultipartBodyBuilder mb=new MultipartBodyBuilder();mb.part("file",new ByteArrayResource(f.getBytes()){public String getFilename(){return f.getOriginalFilename();}});mb.part("folder",folder);mb.part("timestamp",ts);mb.part("api_key",key);mb.part("signature",sig);Map<?,?> m=client.post().uri("/auto/upload").body(mb.build()).retrieve().body(Map.class);return new UploadResult((String)m.get("public_id"),(String)m.get("url"),(String)m.get("secure_url"),(String)m.get("resource_type"),(String)m.get("format"),(Integer)m.get("width"),(Integer)m.get("height"));}catch(Exception e){throw new IllegalStateException("Media upload failed",e);}}
 public void delete(String id){configured();long ts=Instant.now().getEpochSecond();client.post().uri("/image/destroy").body(Map.of("public_id",id,"timestamp",ts,"api_key",key,"signature",sha1("public_id="+id+"&timestamp="+ts+secret))).retrieve().toBodilessEntity();}
 private void configured(){if(cloud.isBlank()||key.isBlank()||secret.isBlank())throw new IllegalStateException("Media storage is not configured");}private static String sha1(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-1").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
